/* Native ring-3 file browser. Legacy desktop Files remains available during migration. */
#include "sdk.h"
static FileInfo files[128];static UiScene scene;
static char folder[128]="/home/user/Documents",name[64]="New file.txt",status[128];
static int window,count,selected=-1,first,field,context,cx,cy,drag_index=-1,dragging,start_x,start_y;
static u32 clicked;static int last_selected=-1;
static void refresh(void){count=List(folder,files,128);if(count<0){copy(status,"无法打开目录。");count=0;}if(selected>=count)selected=-1;if(first>=count)first=count>15?count-15:0;}
static int join(char *out,const char *leaf){u32 n=strlen(folder),m=strlen(leaf);if(n+m+2>=128)return 0;copy(out,folder);if(n>1)out[n++]='/';copy(out+n,leaf);return 1;}
static void open(void){if(selected<0||selected>=count)return;char path[128];if(!join(path,files[selected].name))return;if(files[selected].dir){copy(folder,path);selected=-1;first=0;refresh();}else{u32 n=strlen(path);if(n>=4&&streq(path+n-4,".snx")){if(Spawn(path)<0)copy(status,"程序启动失败。");}else if(SpawnArgs("/home/user/Programs/editor/editor.snx",path)<0)copy(status,"请先安装 /boot/editor.sxp 文本编辑器。");}}
static void draw(void){ui_begin(&scene);const char *buttons[]={"打开","上级","新建文件","新建目录","重命名","删除","刷新"};for(int i=0;i<7;i++)ui_button(&scene,18+i*95,43,88,buttons[i]);ui_fill(&scene,18,84,665,28,field==1?0xe4efff:0xf0f2f5);ui_text(&scene,23,88,folder);ui_fill(&scene,18,118,665,28,field==2?0xe4efff:0xf0f2f5);ui_text(&scene,23,122,name);
 for(int row=0;row<15&&first+row<count;row++){int i=first+row;if(i==selected)ui_fill(&scene,18,161+row*21,665,21,0xdce8f8);ui_text(&scene,23,162+row*21,files[i].name);char text[20];if(files[i].dir)copy(text,"<目录>");else number(files[i].size,text);ui_mono(&scene,555,162+row*21,text,0x617087);}ui_text(&scene,18,486,status);if(context){const char *labels[]={"新建文件","新建目录","重命名","删除"};for(int i=0;i<4;i++)ui_button(&scene,cx,cy+i*28,155,labels[i]);}Scene(window,&scene);}
static void edit(UiEvent *e){char *s=field==1?folder:name;u32 cap=field==1?127:31,n=strlen(s);if(e->type==MSG_TEXT){char text[4];int bytes=text_encode((u32)e->key,text);if(n+(u32)bytes<=cap){memcpy(s+n,text,(u32)bytes);s[n+bytes]=0;}}else if(e->key==1)s[0]=0;else if(e->key==8&&n)s[text_previous(s,n)]=0;else if(e->key>=32&&e->key<127&&n<cap){s[n]=(char)e->key;s[n+1]=0;}else if(e->key==13){field=0;refresh();}}
int main(void){const char *args=Arguments();if(args[0]&&strlen(args)<128)copy(folder,args);window=Window("原生文件管理器 / Ring 3",705,525);if(window<0)return 1;refresh();draw();for(;;){UiEvent e;if(Event(&e)!=0){Yield(1);continue;}if(e.type==MSG_KEY||e.type==MSG_TEXT){if(field)edit(&e);else if(e.type==MSG_KEY){if(e.key==13)open();if(e.key==0x148&&selected>0)selected--;if(e.key==0x150&&selected+1<count)selected++;if(selected<first)first=selected;if(selected>=first+15)first=selected-14;}}
 if(e.type==MSG_CONTEXT){context=1;cx=e.x<525?e.x:525;cy=e.y<370?e.y:370;if(cy<150)cy=150;if(e.y>=161&&e.y<476){int index=first+(e.y-161)/21;if(index<count){selected=index;copy(name,files[index].name);}}}
 if(e.type==MSG_MOUSE_MOVE&&drag_index>=0){if(e.x-start_x>5||start_x-e.x>5||e.y-start_y>5||start_y-e.y>5){dragging=1;copy(status,"松开鼠标移到目录；冲突时保留原文件。");}}
 if(e.type==MSG_MOUSE_UP&&drag_index>=0){int target=first+(e.y-161)/21;if(dragging&&e.y>=161&&e.y<476&&target<count&&target>=0&&files[target].dir&&target!=drag_index){char from[128],to[128];if(join(from,files[drag_index].name)&&join(to,files[target].name)){u32 n=strlen(to),m=strlen(files[drag_index].name);if(n+m+2<128){to[n++]='/';copy(to+n,files[drag_index].name);copy(status,api(SYS_MOVE,(u32)from,(u32)to,0)<0?"移动失败或目标重名。":"文件已移入目录。");refresh();}}}drag_index=-1;dragging=0;}
 if(e.type==MSG_CLICK){if(context){int command=e.x>=cx&&e.x<cx+155&&e.y>=cy&&e.y<cy+112?(e.y-cy)/28+2:-1;context=0;if(command<0){draw();continue;}e.x=18+command*95+40;e.y=56;}if(e.y>=84&&e.y<112)field=1;else if(e.y>=118&&e.y<146)field=2;else if(e.y>=161&&e.y<476){selected=first+(e.y-161)/21;if(selected>=count)selected=-1;field=0;drag_index=selected;start_x=e.x;start_y=e.y;u32 now=(u32)api(SYS_TICKS,0,0,0);if(selected>=0){copy(name,files[selected].name);if(last_selected==selected&&now-clicked<30){drag_index=-1;open();}last_selected=selected;clicked=now;}}else if(e.y>=43&&e.y<69&&e.x>=18&&e.x<683){field=0;int b=(e.x-18)/95;char path[128];status[0]=0;if(b==0)open();else if(b==1){u32 n=strlen(folder);while(n>1&&folder[n-1]!='/')n--;if(n>1)n--;folder[n]=0;selected=-1;first=0;refresh();}else if(b==6)refresh();else if(b==2||b==3){if(!name[0]||streq(name,".")||streq(name,"..")||!join(path,name))copy(status,"无效名称或路径。");else{int valid=1;for(u32 i=0;name[i];i++)if(name[i]=='/'||name[i]=='\\')valid=0;if(!valid)copy(status,"名称不能包含路径分隔符。");else{int r;if(b==3)r=Mkdir(path);else{u8 old[1];int existing=Read(path,old,1);r=existing==S_NOTFOUND?Write(path,"",0):S_EXISTS;}copy(status,r<0?"创建失败或目标已存在。":"已创建。");refresh();}}}else if(selected>=0&&selected<count&&join(path,files[selected].name)){if(b==5){char answer[128];if(!ui_dialog(window,&scene,"确认删除所选项目？",answer,0)){draw();continue;}copy(status,Remove(path,(int)files[selected].dir)<0?"删除失败；只能删除空目录。":"已删除。");refresh();}else if(b==4){char destination[128];int valid=name[0]!=0&&!streq(name,".")&&!streq(name,"..");for(u32 i=0;name[i];i++)if(name[i]=='/'||name[i]=='\\')valid=0;if(!valid||!join(destination,name)||api(SYS_MOVE,(u32)path,(u32)destination,0)<0)copy(status,"重命名失败或目标冲突。");else copy(status,"已重命名。");refresh();}}}}
 draw();}return 0;}
